	async function loadEarlier() {
		if (!historyCursor || refreshing || !loaded) return;
		const ticket = ++sequence;
		refreshing = true;
		earlier.disabled = true;
		refresh.disabled = true;
		headerReads++;
		try {
			alive();
			const data = await api("GET", `/pm/workspaces/${encodeURIComponent(workspaceId)}/threads/${encodeURIComponent(threadId)}?before_message=${historyCursor}`);
			alive();
			if (ticket !== sequence) return;
			if (data.thread?.workspace_id !== workspaceId || data.thread?.thread_id !== threadId) throw Error(t("pm_scope_mismatch"));
			historyCursor = data.next_message_cursor;
			historyExpanded = true;
			renderThread(data);
		} catch (error) {
			if (!retiredView(error) && ticket === sequence) {
				loaded = false;
				lastThreadList = null;
				workspace = null;
				withdrawNames();
				publishContext();
				detailPanel?.close();
				discussionTools?.close();
				brief?.withdraw();
				lifecycle?.withdraw();
				proposalReview?.withdraw();
				for (const section of sourceSections()) section.hidden = true;
				updateForms();
				status.replaceChildren(errorBox(error, {
					summary: t("pm_stale"),
					within: status
				}));
			}
		} finally {
			if (ticket === sequence) {
				refreshing = false;
				refresh.disabled = false;
				earlier.disabled = !loaded;
			}
			settleReadComplete();
		}
	}
	function filterThreads() {
		const query = (uiState.search || "").trim().toLocaleLowerCase();
		const rows = [...threadRows.querySelectorAll(".pm-thread-link")];
		for (const row of rows) row.hidden = !row.dataset.threadSearch.includes(query);
		threadRows.querySelector("[data-discussion-search-empty]")?.remove();
		if (query && !rows.some((row) => !row.hidden)) {
			const empty = emptyState({
				icon: "search",
				title: t("pd_search_empty"),
				text: t("pd_search_empty_help"),
				action: button({
					variant: "ghost",
					label: t("pd_clear_search"),
					onClick: () => {
						uiState.search = "";
						threadSearch.value = "";
						filterThreads();
						threadSearch.focus();
					}
				})
			});
			empty.dataset.discussionSearchEmpty = "";
			threadRows.append(empty);
		}
	}
