		clientGate: () => clientActionGate(state, { post: true }),
		guard: () => assertView(connection),
		namespace: connection.namespace,
		workspaceId: workspaceId === "new" ? null : workspaceId,
		threadId,
		view,
		onEvents,
		errorBox,
